      "ਪੰਜਾਬ ਵਿੱਚ ਤੇਜ਼ੀ ਨਾਲ ਘਟ ਰਹੇ ਜੰਗਲਾਤ ਰਕਬੇ ਅਤੇ ਧਰਤੀ ਹੇਠਲੇ ਪਾਣੀ ਦੇ ਡਿੱਗ ਰਹੇ ਪੱਧਰ ਨੇ ਗੰਭੀਰ ਚਿੰਤਾ ਪੈਦਾ ਕਰ ਦਿੱਤੀ ਹੈ। ਰੁੱਖ ਨਾ ਕੇਵਲ ਸਾਨੂੰ ਆਕਸੀਜਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ ਬਲਕਿ ਧਰਤੀ ਦਾ ਤਾਪਮਾਨ ਸੰਤੁਲਿਤ ਰੱਖਣ ਅਤੇ ਮਿੱਟੀ ਦੇ ਖੋਰੇ ਨੂੰ ਰੋਕਣ ਵਿੱਚ ਵੀ ਮਦਦ ਕਰਦੇ ਹਨ। ਪੰਜਾਬ ਦਾ ਰਾਜ ਰੁੱਖ 'ਟਾਹਲੀ' (ਸ਼ੀਸ਼ਮ) ਹੈ, ਜੋ ਆਪਣੀ ਮਜ਼ਬੂਤ ਲੱਕੜ ਲਈ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਤੋਂ ਇਲਾਵਾ ਕਿੱਕਰ, ਬੋਹੜ ਅਤੇ ਨਿੰਮ ਵਰਗੇ ਰਵਾਇਤੀ ਰੁੱਖ ਵਾਤਾਵਰਨ ਅਤੇ ਸਿਹਤ ਲਈ ਵਰਦਾਨ ਹਨ। ਹਰ ਨਾਗਰਿਕ ਦਾ ਫ਼ਰਜ਼ ਬਣਦਾ ਹੈ ਕਿ ਉਹ ਵੱਧ ਤੋਂ ਵੱਧ ਰੁੱਖ ਲਗਾ ਕੇ ਕੁਦਰਤ ਦਾ ਸੰਤੁਲਨ ਬਹਾਲ ਰੱਖਣ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਵੇ।",
