  "textPa": "ਪੰਜਾਬ ਦਾ ਨਾਮਕਰਨ ਫ਼ਾਰਸੀ ਦੇ ਦੋ ਸ਼ਬਦਾਂ 'ਪੰਜ' ਅਤੇ 'ਆਬ' (ਪਾਣੀ) ਦੇ ਸੁਮੇਲ ਤੋਂ ਹੋਇਆ ਹੈ, ਜਿਸ ਦਾ ਅਰਥ ਹੈ 'ਪੰਜ ਪਾਣੀਆਂ ਦੀ ਧਰਤੀ'। ਇਹ ਪੰਜ ਦਰਿਆ ਸਤਲੁਜ, ਬਿਆਸ, ਰਾਵੀ, ਚਨਾਬ ਅਤੇ ਜਿਹਲਮ ਹਨ। ਇਹਨਾਂ ਦਰਿਆਵਾਂ ਦੁਆਰਾ ਲਿਆਂਦੀ ਗਈ ਉਪਜਾਊ ਜਲੋਢੀ ਮਿੱਟੀ (Alluvial soil) ਨੇ ਪੰਜਾਬ ਨੂੰ ਹਮੇਸ਼ਾ ਭਾਰਤ ਦਾ ਅੰਨ-ਭੰਡਾਰ ਬਣਾਈ ਰੱਖਿਆ। 1947 ਦੀ ਵੰਡ ਮਗਰੋਂ ਚੜ੍ਹਦੇ ਪੰਜਾਬ (ਭਾਰਤੀ ਪੰਜਾਬ) ਦੇ ਹਿੱਸੇ ਮੁੱਖ ਤੌਰ 'ਤੇ ਸਤਲੁਜ, ਬਿਆਸ ਅਤੇ ਕੁਝ ਹਿੱਸਾ ਰਾਵੀ ਦਾ ਆਇਆ। ਨਹਿਰੀ ਸਿੰਜਾਈ ਪ੍ਰਣਾਲੀ ਅਤੇ ਟਿਊਬਵੈੱਲਾਂ ਦੇ ਵਿਸਥਾਰ ਨੇ ਹਰੀ ਕ੍ਰਾਂਤੀ ਵਿੱਚ ਇਤਿਹਾਸਕ ਭੂਮਿਕਾ ਨਿਭਾਈ।",
