  "textPa": "ਲੋਕ-ਨਾਚ ਕਿਸੇ ਵੀ ਖਿੱਤੇ ਦੇ ਲੋਕਾਂ ਦੀਆਂ ਖ਼ੁਸ਼ੀਆਂ, ਜਜ਼ਬਿਆਂ ਅਤੇ ਜੀਵਨ-ਜੋਤ ਦਾ ਸਹਿਜ ਪ੍ਰਗਟਾਵਾ ਹੁੰਦੇ ਹਨ। ਪੰਜਾਬ ਦੇ ਲੋਕ-ਨਾਚਾਂ ਵਿੱਚੋਂ ਮਰਦਾਂ ਦਾ 'ਭੰਗੜਾ' ਅਤੇ ਔਰਤਾਂ ਦਾ 'ਗਿੱਧਾ' ਦੁਨੀਆ ਭਰ ਵਿੱਚ ਪ੍ਰਸਿੱਧ ਹਨ। ਭੰਗੜਾ ਮੂਲ ਰੂਪ ਵਿੱਚ ਵਿਸਾਖੀ ਦੇ ਤਿਉਹਾਰ ਅਤੇ ਕਣਕ ਦੀ ਵਾਢੀ ਦੀ ਖ਼ੁਸ਼ੀ ਨਾਲ ਜੁੜਿਆ ਨਾਚ ਹੈ, ਜਿਸ ਵਿੱਚ ਢੋਲ ਦੀ ਤਾਲ ਪ੍ਰਮੁੱਖ ਹੁੰਦੀ ਹੈ। ਗਿੱਧਾ ਪੰਜਾਬਣਾਂ ਦੇ ਦਿਲ ਦੀਆਂ ਉਮੰਗਾਂ, ਹਾਸੇ-ਮਖੌਲ ਅਤੇ ਦੁੱਖ-ਸੁੱਖ ਦਾ ਬੋਲੀਆਂ ਰਾਹੀਂ ਪ੍ਰਗਟਾਅ ਕਰਦਾ ਹੈ, ਜਿਸ ਵਿੱਚ ਤਾਲੀਆਂ (ਤਾੜੀ) ਦਾ ਸੰਗੀਤ ਅਹਿਮ ਭੂਮਿਕਾ ਨਿਭਾਉਂਦਾ ਹੈ। ਇਹ ਲੋਕ-ਨਾਚ ਪੰਜਾਬੀਆਂ ਦੀ ਅਣਖੀ ਅਤੇ ਜ਼ਿੰਦਾਦਿਲ ਤਬੀਅਤ ਦੇ ਪ੍ਰਤੀਕ ਹਨ।",
