  "textPa": "ਸ਼ਹੀਦ ਭਗਤ ਸਿੰਘ ਭਾਰਤ ਦੇ ਕੌਮੀ ਮੁਕਤੀ ਸੰਗਰਾਮ ਦੇ ਮਹਾਨ ਇਨਕਲਾਬੀ ਚਿੰਤਕ ਸਨ। ਉਹ ਸਿਰਫ਼ ਬੰਬ ਜਾਂ ਪਿਸਤੌਲ ਦੇ ਹਾਮੀ ਨਹੀਂ ਸਨ, ਸਗੋਂ ਉਹਨਾਂ ਦਾ ਮੰਨਣਾ ਸੀ ਕਿ 'ਇਨਕਲਾਬ ਦੀ ਤਲਵਾਰ ਵਿਚਾਰਾਂ ਦੀ ਸਾਣ 'ਤੇ ਤੇਜ਼ ਹੁੰਦੀ ਹੈ'। ਉਹ ਸਮਾਜ ਵਿੱਚੋਂ ਬੇਇਨਸਾਫ਼ੀ, ਲੁੱਟ-ਖਸੁੱਟ, ਗ਼ਰੀਬੀ ਅਤੇ ਫ਼ਿਰਕੂ ਨਫ਼ਰਤ ਨੂੰ ਜੜ੍ਹੋਂ ਪੁੱਟ ਕੇ ਇੱਕ ਸਮਾਨਤਾਵਾਦੀ ਅਤੇ ਧਰਮ-ਨਿਰਪੱਖ ਸਮਾਜ ਦੀ ਸਿਰਜਣਾ ਕਰਨਾ ਚਾਹੁੰਦੇ ਸਨ। ਉਹਨਾਂ ਨੇ ਨੌਜਵਾਨਾਂ ਨੂੰ ਵਿਗਿਆਨਕ ਸੋਚ ਅਪਣਾਉਣ ਅਤੇ ਅੰਧ-ਵਿਸ਼ਵਾਸਾਂ ਤੋਂ ਮੁਕਤ ਹੋਣ ਦਾ ਹੋਕਾ ਦਿੱਤਾ। ਉਹਨਾਂ ਦੀ ਕੁਰਬਾਨੀ ਅੱਜ ਵੀ ਸਮਾਜਿਕ ਨਿਆਂ ਲਈ ਪ੍ਰੇਰਨਾ ਦਾ ਸਰੋਤ ਹੈ।",
